// #da072b (9a1674ab22f6ba3f7dda072b) — отказ провайдера голоса при старте официального звонка не показывается как проблема
// интернета: «בגלל תקלה בצד שלנו, לא אצלכם», только «לפנות לצוות לעזרה», попытка сразу «תקלה טכנית». Настоящая сетевая
// ошибка — по-прежнему «כנראה בגלל תקלה בחיבור לאינטרנט» + «נסו שוב», попытка «בתהליך». Кейсы CALL-031…CALL-033.
// НЕ prod-safe, @data: каждый тест создаёт своего кандидата «QA-AUTO-da072b-…» (link_only) и ТРАТИТ его официальную попытку
// (candidate_start_attempt настоящий). Настоящей голосовой сессии нет: start-voice-session подменён/оборван, api.openai.com
// перехвачен. Кандидаты не удаляются (правило проекта 13.10).
// Это поведение заменило ожидания #d9aa30 после 503; official-start-server-failure.spec.ts переписан 22.10 на сетевой обрыв и повтор на той же попытке.
import { Page } from '@playwright/test';
import { test, expect } from '../../fixtures';
import { runStamp } from '../support/api';
import { Candidate, createCandidateLink, candidateRow, launchCandidate, goToPractice, goToOfficialConfirm, tap, TXT } from './support';

const HASH = '#da072b';
const VOICE = '**/functions/v1/start-voice-session';
const SERVER_FAIL = 'לא הצלחנו להתחיל את השיחה בגלל תקלה בצד שלנו, לא אצלכם. זה לא נחשב לחובתכם, וצוות הגיוס יחזור אליכם לגבי ההמשך.';
const NETWORK_FAIL = 'לא הצלחנו להתחיל את השיחה, כנראה בגלל תקלה בחיבור לאינטרנט. בדקו את החיבור ונסו שוב.';
const CORS = {
  'access-control-allow-origin': '*',
  'access-control-allow-headers': '*',
  'access-control-allow-methods': 'POST, OPTIONS',
  'access-control-expose-headers': '*',
};

let cand: Candidate | undefined;
test.afterEach(async () => {
  await cand?.browser.close();
  cand = undefined;
});

/** Подготовка: кандидат business → Chrome кандидата → экран подтверждения официальной попытки. */
async function prepare(business: Page, label: string) {
  const name = `QA-AUTO-da072b-${label}-${runStamp()}`;
  const link = await createCandidateLink(business, name);
  test.info().annotations.push({ type: 'test-data', description: `кандидат «${name}»: официальная попытка потрачена, не удаляется` });
  cand = await launchCandidate({ width: 390, height: 844 });
  // Страховка: ни одного запроса к настоящему провайдеру голоса.
  await cand.page.route('https://api.openai.com/**', (r) => r.abort('failed'));
  await goToPractice(cand.page, link);
  await goToOfficialConfirm(cand.page);
  return { name, page: cand.page };
}

/** Старт официальной попытки: «מוכן, מתחילים», ответ candidate_start_attempt — настоящий 200. */
async function startOfficial(page: Page) {
  const start = page.waitForResponse((r) => r.url().includes('/rpc/candidate_start_attempt') && r.request().method() === 'POST');
  await tap(page, 'מוכן, מתחילים');
  expect((await start).status(), 'candidate_start_attempt').toBe(200);
}

/** Отказ «на нашей стороне»: data-reason=server, точный текст, только «לפנות לצוות לעזרה». */
async function expectServerFailure(page: Page) {
  const failure = page.getByTestId('start-failure');
  await expect(failure).toBeVisible({ timeout: 15_000 });
  await expect(failure).toHaveAttribute('data-reason', 'server');
  await expect(failure.getByRole('alert')).toHaveText(SERVER_FAIL);
  await expect(failure.getByRole('button')).toHaveText([TXT.help]);
  await expect(failure.getByRole('button', { name: TXT.retry })).toHaveCount(0);
  await expect(failure).not.toContainText('אינטרנט');
  await expect(failure).not.toContainText('חיבור');
}

/** Статус кандидата в списке business (перезагрузка списка, пока статус не совпадёт). */
async function expectListStatus(business: Page, name: string, want: string, notWant: string) {
  await expect
    .poll(async () => (await (await candidateRow(business, name)).innerText()).replace(/\s+/g, ' '), {
      message: `строка «${name}» в /candidates должна содержать «${want}»`,
      timeout: 30_000,
    })
    .toContain(want);
  await expect(await candidateRow(business, name)).not.toContainText(notWant);
}

test.describe(`Звонок кандидата — отказ провайдера голоса при старте (${HASH})`, () => {
  test(`503 provider_unavailable на start-voice-session → «תקלה בצד שלנו, לא אצלכם», только «לפנות לצוות לעזרה»; у business «תקלה טכנית» @desktop @data ${HASH}`, async ({ asUser }) => {
    test.setTimeout(4 * 60_000);
    const business = await asUser('business');
    const { name, page } = await prepare(business, 'M1');

    await page.route(VOICE, async (route) => {
      if (route.request().method() === 'OPTIONS') return route.fulfill({ status: 204, headers: CORS });
      return route.fulfill({ status: 503, headers: { ...CORS, 'content-type': 'application/json' }, body: JSON.stringify({ error: 'provider_unavailable' }) });
    });
    await startOfficial(page);

    // Источник: AC — «סירוב של ספק הקול … אינו מוצג למועמד כבעיית אינטרנט; מוצג הסבר שהתקלה אינה אצלו ונתיב פנייה».
    await expectServerFailure(page);
    // Источник: AC — «הניסיון לא נשאר בסטטוס «בתהליך» אחרי כשל כזה».
    await expectListStatus(business, name, 'תקלה טכנית', 'בתהליך');
  });

  test(`провайдер 429 insufficient_quota на connect_url (как 14.10) → то же сообщение «תקלה בצד שלנו»; у business «תקלה טכנית» @desktop @data ${HASH}`, async ({ asUser }) => {
    test.setTimeout(4 * 60_000);
    const business = await asUser('business');
    const { name, page } = await prepare(business, 'M2');

    // start-voice-session отвечает «сессией», connect_url провайдера — 429 insufficient_quota (настоящей сессии нет).
    await page.route(VOICE, async (route) => {
      if (route.request().method() === 'OPTIONS') return route.fulfill({ status: 204, headers: CORS });
      const attemptId = (route.request().postDataJSON() as { attempt_id?: string })?.attempt_id;
      return route.fulfill({
        status: 200,
        headers: { ...CORS, 'content-type': 'application/json' },
        body: JSON.stringify({
          attempt_id: attemptId,
          provider_config_id: 'dd0a99a7-1c3b-41d0-9b52-0379a4e7b864',
          max_duration_seconds: 540,
          session: { protocol: 'webrtc_sdp', client_secret: 'ek_qa_mock_not_real', connect_url: 'https://api.openai.com/v1/realtime/calls', data_channel: 'oai-events' },
          bookkeeping_tools: [],
        }),
      });
    });
    await page.unroute('https://api.openai.com/**');
    await page.route('https://api.openai.com/**', async (route) => {
      if (route.request().method() === 'OPTIONS') return route.fulfill({ status: 204, headers: CORS });
      return route.fulfill({
        status: 429,
        headers: { ...CORS, 'content-type': 'application/json' },
        body: JSON.stringify({ error: { message: 'You exceeded your current quota', type: 'insufficient_quota', code: 'insufficient_quota' } }),
      });
    });
    const quota = page.waitForResponse((r) => r.url().startsWith('https://api.openai.com/') && r.request().method() === 'POST');
    await startOfficial(page);
    expect((await quota).status(), 'подменённый ответ провайдера').toBe(429);

    // Источник: «מה קיים» 14.10 (429 insufficient_quota показывался как интернет) + AC.
    await expectServerFailure(page);
    await expectListStatus(business, name, 'תקלה טכנית', 'בתהליך');
  });

  test(`настоящая сетевая ошибка (start-voice-session оборван) → «כנראה בגלל תקלה בחיבור לאינטרנט» + «נסו שוב»; у business «בתהליך» @desktop @data ${HASH}`, async ({ asUser }) => {
    test.setTimeout(4 * 60_000);
    const business = await asUser('business');
    const { name, page } = await prepare(business, 'M3');

    await page.route(VOICE, (route) =>
      route.request().method() === 'OPTIONS' ? route.fulfill({ status: 204, headers: CORS }) : route.abort('internetdisconnected'),
    );
    await startOfficial(page);

    // Источник: комментарий программиста к #da072b — «תקלת רשת אמיתית … ממשיכה להציג את הודעת האינטרנט, והניסיון נשאר פתוח».
    const failure = page.getByTestId('start-failure');
    await expect(failure).toBeVisible({ timeout: 15_000 });
    await expect(failure).toHaveAttribute('data-reason', 'network');
    await expect(failure.getByRole('alert')).toHaveText(NETWORK_FAIL);
    await expect(failure.getByRole('button', { name: TXT.retry })).toBeVisible();
    await expect(failure.getByRole('button', { name: TXT.help })).toBeVisible();
    await expect(failure.getByRole('button', { name: 'לסיים ולדווח על תקלה' })).toBeVisible();
    await expect(failure).not.toContainText('בצד שלנו');

    await expectListStatus(business, name, 'בתהליך', 'תקלה טכנית');
  });
});
